  if (X.dientes) { if (!side) for (let x = hx - 3; x <= hx + 2; x++) { p.set(x, mo, (x & 1) ? C('#d8d0c0') : C('#0a0608')); p.set(x, mo + 1, C('#0a0608')); } else for (let k = 0; k < 3; k++) p.set((d < 0 ? hx - 6 : hx + 3) + k * d, mo, (k & 1) ? C('#0a0608') : C('#d8d0c0')); }
