SECRETS.forEach(S => { if (!S.loc && ['linterna', 'simbolos', 'altares', 'campana', 'corrupcion', 'mascara', 'jardin', 'nombre', 'conjuros', 'rosas', 'mascotas'].includes(S.id)) { S.loc = () => VR_WPOS.portal; S.lt = L2('Portal antiguo', 'Ancient portal'); } });
let GSEC = null;
function renderSecrets() { const P = G.P; P.secH = P.secH || {}; const S = SECRETS.find(s => s.id === GSEC), tx = v => typeof v === 'function' ? v() : v;
  let det = `<p class="hint">${L2('Todo lo escondido del Velo Roto. Toca uno: verás los pasos y puedes pedir pistas (una a una, para no destripar más de lo que quieras).', 'Everything hidden in the Broken Veil. Tap one: you will see the steps and can ask for hints (one at a time, so nothing is spoiled beyond what you want).')}</p>`;
  if (S) { const nh = P.secH[S.id] || 0, loc = S.loc && S.loc(); det = `<h4>${esc(S.n)} ${S.done(P) ? '✓' : ''}</h4>` + S.steps.map((s, i) => `<div class="gsrc"><span>${i + 1}. ${esc(tx(s))}</span></div>`).join('') + S.hints.slice(0, nh).map((h, i) => `<div class="gsrc"><span>💡 ${esc(tx(h))}</span></div>`).join('') +
    `<div class="row">${nh < S.hints.length ? `<button class="btn sm" id="secH">💡 ${L2('Pista', 'Hint')} ${nh + 1}/${S.hints.length}</button>` : ''}${loc ? guiaFollowBtn({ loc, t: S.lt || S.n }, S.n) : ''}</div>`; }
  openModal(`<div class="frame guia"><h3>🔎 ${L2('Dónde conseguir', 'Where to get it')}</h3><div class="chips"><button class="chip" data-gt2="mat">${L2('Materiales', 'Materials')}</button><button class="chip" data-gt2="eq">${L2('Equipo', 'Gear')}</button><button class="chip" data-gt2="cos">${L2('Cosméticos', 'Cosmetics')}</button><button class="chip" data-gt2="boss">${L2('Jefes', 'Bosses')}</button><button class="chip on">🗝 ${L2('Secretos', 'Secrets')}</button></div>
    <div class="gcols"><div class="glist">${SECRETS.map(s => `<button class="gitem ${GSEC === s.id ? 'sel' : ''} ${s.done(P) ? 'own' : ''}" data-sec="${s.id}"><span>${esc(s.n)}</span>${s.done(P) ? ' ✓' : ''}</button>`).join('')}</div><div class="gdet">${det}</div></div><div class="row"><button class="btn" id="gClose">${L2('Cerrar', 'Close')}</button></div></div>`, 'guiamod');
  $('#gClose').onclick = closeModal; $$('[data-gt2]').forEach(b => b.onclick = () => { GUIA.tab = b.dataset.gt2; GUIA.sel = null; renderGuia(); });
  $$('[data-sec]').forEach(b => b.onclick = () => { GSEC = b.dataset.sec; renderSecrets(); }); const h = $('#secH'); if (h) h.onclick = () => { P.secH[GSEC] = (P.secH[GSEC] || 0) + 1; markDirty(); renderSecrets(); };
  $$('[data-wp]').forEach(b => b.onclick = () => { const [x, y] = b.dataset.wp.split(',').map(Number); if (P.wp && P.wp.x === x && P.wp.y === y) P.wp = null; else { P.wp = { x, y, t: b.dataset.wl }; toast(L2('La flecha dorada te lleva a: ', 'The golden arrow leads to: ') + b.dataset.wl, 'info', 3); } markDirty(); renderSecrets(); }); }
{ const _rg = renderGuia; renderGuia = function () { if (GUIA.tab === 'sec') return renderSecrets(); const r = _rg.apply(this, arguments); const ch = $('.guia .chips'); if (ch && !ch.querySelector('[data-gsec]')) { const b = document.createElement('button'); b.className = 'chip'; b.dataset.gsec = 1; b.textContent = '🗝 ' + L2('Secretos', 'Secrets'); b.onclick = () => { GUIA.tab = 'sec'; renderSecrets(); }; const off = ch.querySelector('#gOff'); ch.insertBefore(b, off || null); } return r; }; }
// guía de equipo y jefes nuevos
{ const _bw = bossWhere; bossWhere = function (id) { if (id === 'rey_rosas') return { where: L2('Velo Roto: Bosque de la Torre Hueca', 'Broken Veil: Hollow Tower Woods'), loc: VR_WPOS.portal || null }; return _bw(id); }; }
{ const _is = itemSources; itemSources = function (id) { const out = _is(id); if (id === 'pocion_sangre_limpia') out.unshift([L2('Corvel el Encapuchado (Torre Hueca, Velo Roto)', 'Corvel the Hooded (Hollow Tower, Broken Veil)'), null]); if (id === 'brebaje_caldera') out.unshift([L2('Grizzla, la Bruja de la Caldera (Torre Hueca, Velo Roto)', 'Grizzla, the Cauldron Witch (Hollow Tower, Broken Veil)'), null]);
  for (const s of out) { const m = VR4_MOBS.find(v => s[0].includes(MOBS[v[0]].n) && !s[0].includes(L2('Velo Roto', 'Broken Veil'))); if (m) { const Z = VR_ZONES.find(z => z.pool.includes(m[0])); s[0] += ' · ' + L2('Velo Roto', 'Broken Veil') + (Z ? ': ' + Z.n : ''); s[1] = VR_WPOS.portal ? { loc: VR_WPOS.portal, t: L2('Portal antiguo', 'Ancient portal') } : null; } } return out; }; }
